package edu.pe.cibertec.saibm.membresia.infrastructure.persistence;
import java.time.Instant; import java.util.UUID; import jakarta.persistence.*; import edu.pe.cibertec.saibm.membresia.domain.model.MembershipAssignment;
@Entity @Table(name="membership_assignments") public class AssignmentJpaEntity {@Id UUID id;@Column(name="user_id",nullable=false)String userId;@Column(name="plan_id",nullable=false)UUID planId;@Column(name="plan_code",nullable=false)String planCode;@Column(name="plan_version",nullable=false)int planVersion;@Column(name="reservation_limit",nullable=false)int reservationLimit;@Column(name="valid_from",nullable=false)Instant validFrom;Instant validUntil;boolean active;@Column(name="idempotency_key",unique=true,nullable=false)String idempotencyKey;@Column(name="request_hash",nullable=false)String requestHash;@Column(name="legacy_user_id")String legacyUserId;protected AssignmentJpaEntity(){}AssignmentJpaEntity(MembershipAssignment a){id=a.id();userId=a.userId();planId=a.planId();planCode=a.planCode();planVersion=a.planVersion();reservationLimit=a.reservationLimit();validFrom=a.validFrom();validUntil=a.validUntil();active=a.active();idempotencyKey=a.idempotencyKey();requestHash=a.requestHash();legacyUserId=a.legacyUserId();}MembershipAssignment domain(){return new MembershipAssignment(id,userId,planId,planCode,planVersion,reservationLimit,validFrom,validUntil,active,idempotencyKey,requestHash,legacyUserId);}}
